import numpy as np, collections
from PIL import Image, ImageFilter
im=Image.open('radiograph.jpg').convert('L')
a=np.asarray(im).astype(np.float32)
big=np.asarray(im.filter(ImageFilter.GaussianBlur(30))).astype(np.float32)
diff=big-a
H,W=diff.shape
m=np.zeros_like(diff); m[int(0.26*H):int(0.96*H), int(0.21*W):int(0.79*W)]=1
diff*=m
h,w=H//4,W//4
d=diff[:h*4,:w*4].reshape(h,4,w,4).max(axis=(1,3))
for T in (60,80):
  th=d>T
  lab=np.zeros(th.shape,int); cur=0; comps=[]
  for y in range(h):
    for x in range(w):
      if th[y,x] and lab[y,x]==0:
        cur+=1; q=collections.deque([(y,x)]); lab[y,x]=cur; pix=[]
        while q:
          cy,cx=q.popleft(); pix.append((cy,cx))
          for dy in(-1,0,1):
            for dx in(-1,0,1):
              ny,nx=cy+dy,cx+dx
              if 0<=ny<h and 0<=nx<w and th[ny,nx] and lab[ny,nx]==0:
                lab[ny,nx]=cur; q.append((ny,nx))
        pix=np.array(pix)
        if len(pix)>=10:
          comps.append((len(pix),pix[:,1].mean()*4/W,pix[:,0].mean()*4/H,(np.ptp(pix[:,1])+1)*4/W,(np.ptp(pix[:,0])+1)*4/H))
  comps.sort(reverse=True)
  print('--- T',T,'ncomp',len(comps))
  for c in comps[:20]:
    print(int(c[0]),'cx%.3f cy%.3f w%.3f h%.3f'%(c[1],c[2],c[3],c[4]))
