import numpy as np, collections
from PIL import Image, ImageFilter
im=Image.open('radiograph.jpg').convert('L')
a=np.asarray(im).astype(np.float32)
H,W=a.shape
for rad,lo,hi,label in [(12,0.30,0.44,'UP'),(12,0.68,0.90,'DN')]:
    big=np.asarray(im.filter(ImageFilter.GaussianBlur(rad))).astype(np.float32)
    diff=big-a
    m=np.zeros_like(diff); m[int(lo*H):int(hi*H), int(0.22*W):int(0.78*W)]=1
    # smooth diff then find local maxima
    dsm=np.asarray(Image.fromarray(np.clip(diff*m+128,0,255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(4))).astype(np.float32)-128
    th=dsm>40
    lab=np.zeros(th.shape,int); comps=[]
    for y in range(th.shape[0]):
        for x in range(th.shape[1]):
            if th[y,x] and lab[y,x]==0:
                q=collections.deque([(y,x)]); lab[y,x]=1; pix=[]
                while q:
                    cy,cx=q.popleft(); pix.append((cy,cx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<th.shape[0] and 0<=nx<th.shape[1] and th[ny,nx] and lab[ny,nx]==0:
                                lab[ny,nx]=1; q.append((ny,nx))
                pix=np.array(pix)
                if len(pix)>=50:
                    comps.append((len(pix),pix[:,1].mean()/W,pix[:,0].mean()/H,(np.ptp(pix[:,1])+1)/W,(np.ptp(pix[:,0])+1)/H,dsm[pix[:,0],pix[:,1]].max()))
    comps.sort(reverse=True)
    print('===',label,len(comps))
    for c in comps[:12]:
        print(int(c[0]),'cx%.3f cy%.3f w%.3f h%.3f peak%.0f'%(c[1],c[2],c[3],c[4],c[5]))
